#include "metalrobo/MetalUnifiedQualitySolver.hpp"
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>
using namespace metalrobo;
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("input");std::ifstream f(argv[1],std::ios::binary);std::uint32_t N,n,h;f.read((char*)&N,4);f.read((char*)&n,4);f.read((char*)&h,4);if(N!=64||n==0||h==0||h+1>n)throw std::runtime_error("header");std::size_t m=h+1;std::vector<float>A(N*n*n),J(N*m*n),b(N*m),v(N*n),warm(N*n,0),imp(N*m,0);for(auto* a:{&A,&J,&b,&v})f.read((char*)a->data(),a->size()*sizeof(float));if(!f||f.peek()!=std::char_traits<char>::eof())throw std::runtime_error("payload");std::vector<MRUnifiedQualityBlockGPU>blocks(m);for(unsigned i=0;i<m;++i){auto&z=blocks[i];bool hard=i<h;z.layout={i,1,MR_UNIFIED_QUALITY_SCALAR_INTERVAL,hard?MR_UNIFIED_QUALITY_BLOCK_HARD_EQUALITY:0u};z.stableKey={500+i,0,0,0};z.scale0=z.scale1={1,1,1,1};z.regularization0=z.regularization1={.02f,1,1,1};z.boundsAndShift={hard?-std::numeric_limits<float>::max():0.f,std::numeric_limits<float>::max(),0,0};}MetalUnifiedQualityProblem p;p.problemCount=N;p.generalizedVelocityCount=n;p.rowCount=m;p.blocks=blocks;p.dynamics=A;p.jacobian=J;p.bias=b;p.freeVelocity=v;p.warmVelocity=warm;p.warmImpulses=imp;MetalUnifiedQualityConfig c;c.maximumNewtonIterations=40;c.optimalityTolerance=1e-5f;c.feasibilityTolerance=2e-5f;MetalUnifiedQualityResult r;auto d=solveMetalUnifiedQuality(p,r,c);std::cout<<std::setprecision(10)<<"{\"success\":"<<(d.succeeded()?"true":"false")<<",\"dispatched\":"<<(d.dispatched?"true":"false")<<",\"published\":"<<(d.published?"true":"false")<<",\"status\":"<<d.firstGPUStatusCode<<",\"message\":"<<std::quoted(d.message)<<",\"velocity\":[";for(size_t i=0;i<r.velocity.size();++i){if(i)std::cout<<',';std::cout<<r.velocity[i];}std::cout<<"],\"impulse\":[";for(size_t i=0;i<r.impulses.size();++i){if(i)std::cout<<',';std::cout<<r.impulses[i];}std::cout<<"],\"paths\":[";for(size_t i=0;i<r.statuses.size();++i){if(i)std::cout<<',';std::cout<<r.statuses[i].solvePath;}std::cout<<"]}\n";return d.succeeded()?0:2;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
